-- Target backend migration. Not deployed by the Capacitor/Base44 preview APK.
begin;
revoke create on schema public from public;
create table public.mvp_users(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',time_zone text not null default 'UTC',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz);
create table public.mvp_settings(user_id uuid primary key references public.mvp_users(id) on delete cascade,preferences jsonb not null default '{"maxProjects":3,"maxToday":3,"requireEvidence":true,"stallDays":3}',version integer not null default 1,updated_at timestamptz not null default now(),check(jsonb_typeof(preferences)='object'),check((preferences->>'maxProjects')::int between 1 and 20),check((preferences->>'maxToday')::int between 1 and 30));
create table public.mvp_projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,title text not null check(length(trim(title))>0),outcome text not null default '',definition_of_done text not null default '',status text not null default 'planned' check(status in('planned','active','paused','completed','archived')),next_action_task_id uuid,progress_mode text not null default 'tasks' check(progress_mode in('tasks','manual')),progress numeric not null default 0 check(progress between 0 and 100),last_activity_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,unique(id,user_id),check((status='completed')=(completed_at is not null)),check(status<>'completed' or progress=100));
create table public.mvp_inbox_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,content text not null,file_key text,status text not null default 'inbox' check(status in('inbox','processed','archived')),ai_proposal jsonb,converted_task_id uuid,converted_project_id uuid,converted_artifact_id uuid,processed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,unique(id,user_id),check(num_nonnulls(converted_task_id,converted_project_id,converted_artifact_id)<=1),check(status<>'processed' or (num_nonnulls(converted_task_id,converted_project_id,converted_artifact_id)=1 and processed_at is not null)),check(status<>'inbox' or num_nonnulls(converted_task_id,converted_project_id,converted_artifact_id)=0));
create table public.mvp_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,project_id uuid,source_inbox_id uuid,parent_id uuid,title text not null check(length(trim(title))>0),description text not null default '',status text not null default 'todo' check(status in('todo','doing','blocked','done')),due_at timestamptz,today_date date,recurrence jsonb,support_strategy jsonb not null default '{}',completion_reflection jsonb,completed_at timestamptz,cancelled_at timestamptz,cancel_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,unique(id,user_id),unique(id,user_id,project_id),foreign key(project_id,user_id) references public.mvp_projects(id,user_id) deferrable initially deferred,foreign key(source_inbox_id,user_id) references public.mvp_inbox_items(id,user_id) deferrable initially deferred,foreign key(parent_id,user_id) references public.mvp_tasks(id,user_id) deferrable initially deferred,check(parent_id is distinct from id),check((status='done')=(completed_at is not null)),check(cancelled_at is null or length(trim(cancel_reason))>0));
create table public.mvp_artifacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,project_id uuid,task_id uuid,source_inbox_id uuid,kind text not null check(kind in('note','link','file','output')),title text not null,content text,storage_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,unique(id,user_id),foreign key(project_id,user_id) references public.mvp_projects(id,user_id) deferrable initially deferred,foreign key(task_id,user_id) references public.mvp_tasks(id,user_id) deferrable initially deferred,foreign key(task_id,user_id,project_id) references public.mvp_tasks(id,user_id,project_id) deferrable initially deferred,foreign key(source_inbox_id,user_id) references public.mvp_inbox_items(id,user_id) deferrable initially deferred,check(nullif(trim(content),'') is not null or storage_key is not null));
create table public.mvp_daily_briefs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,local_date date not null,time_zone_snapshot text not null,task_ids uuid[] not null default '{}',explanation text not null default '',generated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,unique(user_id,local_date));
create table public.mvp_focus_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.mvp_users(id) on delete cascade,task_id uuid not null,planned_seconds integer not null check(planned_seconds between 60 and 7200),started_at timestamptz not null default now(),ended_at timestamptz,paused_seconds integer not null default 0 check(paused_seconds>=0),status text not null default 'running' check(status in('running','paused','ended')),outcome text,strategy_tried text,helpfulness text check(helpfulness in('helped','partly','different') or helpfulness is null),lesson text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,deleted_at timestamptz,foreign key(task_id,user_id) references public.mvp_tasks(id,user_id),check((status='ended')=(ended_at is not null)));
create unique index mvp_one_open_focus on public.mvp_focus_sessions(user_id) where status in('running','paused') and deleted_at is null;
create table public.mvp_mutation_receipts(user_id uuid not null references public.mvp_users(id) on delete cascade,mutation_id uuid not null,request_hash text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(user_id,mutation_id));
create table public.mvp_recurrence_occurrences(user_id uuid not null references public.mvp_users(id) on delete cascade,series_id uuid not null,occurrence_at timestamptz not null,task_id uuid not null,primary key(user_id,series_id,occurrence_at),foreign key(task_id,user_id) references public.mvp_tasks(id,user_id));
alter table public.mvp_projects add foreign key(next_action_task_id,user_id) references public.mvp_tasks(id,user_id) deferrable initially deferred;
alter table public.mvp_inbox_items add foreign key(converted_task_id,user_id) references public.mvp_tasks(id,user_id) deferrable initially deferred,add foreign key(converted_project_id,user_id) references public.mvp_projects(id,user_id) deferrable initially deferred,add foreign key(converted_artifact_id,user_id) references public.mvp_artifacts(id,user_id) deferrable initially deferred;
create index on public.mvp_tasks(user_id,today_date) where deleted_at is null and status<>'done';
create index on public.mvp_tasks(user_id,project_id) where deleted_at is null;
create index on public.mvp_projects(user_id,status) where deleted_at is null;
create index on public.mvp_inbox_items(user_id,status,created_at desc) where deleted_at is null;

create function public.mvp_stamp() returns trigger language plpgsql set search_path=public,pg_temp as $$begin new.updated_at=now();new.version=old.version+1;return new;end$$;
do $$declare name text;begin foreach name in array array['mvp_users','mvp_settings','mvp_projects','mvp_inbox_items','mvp_tasks','mvp_artifacts','mvp_focus_sessions'] loop execute format('create trigger stamp before update on public.%I for each row execute function public.mvp_stamp()',name);end loop;end$$;
create function public.mvp_check_version(actual integer,data jsonb) returns void language plpgsql as $$begin if data->>'expected_version' is null or actual<>(data->>'expected_version')::integer then raise exception using errcode='40001',message='Record changed. Refresh and review before retrying.';end if;end$$;
create function public.mvp_validate_state() returns trigger language plpgsql set search_path=public,pg_temp as $$
declare uid uuid;settings jsonb;p public.mvp_projects;t public.mvp_tasks;parent public.mvp_tasks;begin
 uid=coalesce(new.user_id,old.user_id);select preferences into settings from public.mvp_settings where user_id=uid;
 if (select count(*) from public.mvp_projects where user_id=uid and status='active' and deleted_at is null)>(settings->>'maxProjects')::int then raise exception 'Active project capacity exceeded';end if;
 if (select count(*) from public.mvp_tasks where user_id=uid and today_date=(now() at time zone (select time_zone from public.mvp_users where id=uid))::date and status<>'done' and cancelled_at is null and deleted_at is null)>(settings->>'maxToday')::int then raise exception 'Today capacity exceeded';end if;
 for p in select * from public.mvp_projects where user_id=uid and deleted_at is null loop
  if p.status='active' then
   if nullif(trim(p.definition_of_done),'') is null then raise exception 'Active project needs a definition of done';end if;
   if exists(select 1 from public.mvp_tasks where project_id=p.id and deleted_at is null and cancelled_at is null and status<>'done') and not exists(select 1 from public.mvp_tasks where id=p.next_action_task_id and project_id=p.id and user_id=uid and deleted_at is null and cancelled_at is null and status<>'done') then raise exception 'Active project needs a valid next action';end if;
  elsif p.status='completed' and exists(select 1 from public.mvp_tasks where project_id=p.id and deleted_at is null and cancelled_at is null and status<>'done') then raise exception 'Finished project has unresolved tasks';end if;
 end loop;
 for t in select * from public.mvp_tasks where user_id=uid and deleted_at is null and parent_id is not null loop
  select * into parent from public.mvp_tasks where id=t.parent_id and user_id=uid;
  if not found or parent.deleted_at is not null or parent.project_id is distinct from t.project_id then raise exception 'Invalid parent task or mismatched project';end if;
  if exists(with recursive ancestors as(select id,parent_id from public.mvp_tasks where id=t.parent_id union select x.id,x.parent_id from public.mvp_tasks x join ancestors a on x.id=a.parent_id)select 1 from ancestors where id=t.id)then raise exception 'Circular subtask hierarchy';end if;
 end loop;
 return null;
end$$;
do $$declare name text;begin foreach name in array array['mvp_tasks','mvp_projects','mvp_settings']loop execute format('create constraint trigger valid_state after insert or update on public.%I deferrable initially deferred for each row execute function public.mvp_validate_state()',name);end loop;end$$;

create function public.mvp_command(p_mutation_id uuid,p_command text,p_data jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_variable
declare uid uuid:=auth.uid();id uuid:=nullif(p_data->>'id','')::uuid;hash text:=md5(p_command||p_data::text);receipt public.mvp_mutation_receipts;result jsonb;project public.mvp_projects;task public.mvp_tasks;capture public.mvp_inbox_items;focus public.mvp_focus_sessions;artifact_id uuid;destination uuid;definition text;pref jsonb;next_occurrence timestamptz;series_uuid uuid;new_task_id uuid;begin
 if p_data->>'file_key' is not null and left(p_data->>'file_key',37)<>(uid::text||'/') then raise exception 'File key must belong to your account';end if;
 if uid is null then raise exception using errcode='42501',message='Sign in required';end if;
 insert into public.mvp_users(id)values(uid)on conflict do nothing;insert into public.mvp_settings(user_id)values(uid)on conflict do nothing;
 perform 1 from public.mvp_users where mvp_users.id=uid and deleted_at is null for update;if not found then raise exception 'Account unavailable';end if;
 select * into receipt from public.mvp_mutation_receipts where user_id=uid and mutation_id=p_mutation_id;
 if found then if receipt.request_hash<>hash then raise exception 'Mutation ID reused with different data';end if;return receipt.result;end if;
 select preferences into pref from public.mvp_settings where user_id=uid;
 case p_command
 when 'save_settings' then
  update public.mvp_settings set preferences=preferences||coalesce(p_data->'preferences','{}') where user_id=uid;
  if p_data ? 'time_zone' then if not exists(select 1 from pg_timezone_names where name=p_data->>'time_zone')then raise exception 'Invalid timezone';end if;update public.mvp_users set time_zone=p_data->>'time_zone' where mvp_users.id=uid;end if;
  select to_jsonb(s)into result from public.mvp_settings s where user_id=uid;
 when 'create_capture' then
  insert into public.mvp_inbox_items(id,user_id,content,file_key)values(coalesce(id,gen_random_uuid()),uid,coalesce(p_data->>'content',''),p_data->>'file_key')returning to_jsonb(mvp_inbox_items.*)into result;
 when 'create_project' then
  insert into public.mvp_projects(id,user_id,title,outcome,definition_of_done)values(coalesce(id,gen_random_uuid()),uid,p_data->>'title',coalesce(p_data->>'outcome',''),coalesce(p_data->>'definition_of_done',''))returning to_jsonb(mvp_projects.*)into result;
 when 'create_task' then
  insert into public.mvp_tasks(id,user_id,project_id,parent_id,title,description,today_date,due_at,recurrence)values(coalesce(id,gen_random_uuid()),uid,nullif(p_data->>'project_id','')::uuid,nullif(p_data->>'parent_id','')::uuid,p_data->>'title',coalesce(p_data->>'description',''),nullif(p_data->>'today_date','')::date,nullif(p_data->>'due_at','')::timestamptz,case when p_data->>'frequency' in('daily','weekly','monthly')then jsonb_build_object('frequency',p_data->>'frequency')else null end)returning to_jsonb(mvp_tasks.*)into result;
 when 'activate_project','pause_project' then
  select * into project from public.mvp_projects where mvp_projects.id=id and user_id=uid and deleted_at is null for update;if not found then raise exception using errcode='42501',message='Project unavailable';end if;perform public.mvp_check_version(project.version,p_data);
  if project.status='completed' then raise exception 'Reopen a finished project explicitly';end if;
  update public.mvp_projects set status=case when p_command='activate_project' then 'active' else 'paused' end,definition_of_done=coalesce(p_data->>'definition_of_done',definition_of_done),next_action_task_id=case when p_data ? 'next_action_task_id' then nullif(p_data->>'next_action_task_id','')::uuid else next_action_task_id end where mvp_projects.id=id returning to_jsonb(mvp_projects.*)into result;
 when 'assign_today','complete_task','reopen_task','update_task' then
  select * into task from public.mvp_tasks where mvp_tasks.id=id and user_id=uid and deleted_at is null for update;if not found then raise exception using errcode='42501',message='Task unavailable';end if;perform public.mvp_check_version(task.version,p_data);
  if p_command='assign_today' then update public.mvp_tasks set today_date=nullif(p_data->>'today_date','')::date where mvp_tasks.id=id;
  elsif p_command='complete_task' then update public.mvp_tasks set status='done',completed_at=now(),completion_reflection=p_data->'reflection' where mvp_tasks.id=id;update public.mvp_focus_sessions set status='ended',ended_at=now(),outcome='task_completed' where task_id=id and user_id=uid and status in('running','paused');
  elsif p_command='reopen_task' then update public.mvp_tasks set status='todo',completed_at=null where mvp_tasks.id=id;
  else update public.mvp_tasks set title=coalesce(p_data->>'title',title),parent_id=case when p_data ? 'parent_id' then nullif(p_data->>'parent_id','')::uuid else parent_id end,project_id=case when p_data ? 'project_id' then nullif(p_data->>'project_id','')::uuid else project_id end where mvp_tasks.id=id;end if;
  if p_command='complete_task' and task.status<>'done' and task.recurrence->>'frequency' in('daily','weekly','monthly')then
   series_uuid=coalesce(nullif(task.recurrence->>'series_id','')::uuid,task.id);
   next_occurrence=((coalesce(task.due_at,now())at time zone(select time_zone from public.mvp_users where mvp_users.id=uid))+case task.recurrence->>'frequency' when 'daily'then interval '1 day' when 'weekly'then interval '1 week' else interval '1 month' end)at time zone(select time_zone from public.mvp_users where mvp_users.id=uid);
   if not exists(select 1 from public.mvp_recurrence_occurrences where user_id=uid and series_id=series_uuid and occurrence_at=next_occurrence)then
    insert into public.mvp_tasks(user_id,project_id,parent_id,title,description,due_at,recurrence,support_strategy)values(uid,task.project_id,task.parent_id,task.title,task.description,next_occurrence,task.recurrence||jsonb_build_object('series_id',series_uuid),task.support_strategy)returning mvp_tasks.id into new_task_id;
    insert into public.mvp_recurrence_occurrences(user_id,series_id,occurrence_at,task_id)values(uid,series_uuid,next_occurrence,new_task_id);
   end if;
  end if;
  if task.project_id is not null then update public.mvp_projects set next_action_task_id=(select t.id from public.mvp_tasks t where t.project_id=task.project_id and t.user_id=uid and t.status<>'done' and t.cancelled_at is null and t.deleted_at is null order by t.created_at limit 1),progress=case when progress_mode='tasks'then coalesce((select round(100.0*count(*)filter(where t.status='done')/nullif(count(*),0))from public.mvp_tasks t where t.project_id=task.project_id and t.deleted_at is null and t.cancelled_at is null),0)else progress end,last_activity_at=case when p_command in('complete_task','reopen_task')then now()else last_activity_at end where mvp_projects.id=task.project_id;end if;
  select to_jsonb(t)into result from public.mvp_tasks t where t.id=id;
 when 'convert_capture' then
  select * into capture from public.mvp_inbox_items where mvp_inbox_items.id=id and user_id=uid and deleted_at is null for update;if not found then raise exception using errcode='42501',message='Capture unavailable';end if;
  if capture.status='processed' then result=jsonb_build_object('task_id',capture.converted_task_id,'project_id',capture.converted_project_id,'artifact_id',capture.converted_artifact_id);
  else perform public.mvp_check_version(capture.version,p_data);destination=coalesce(nullif(p_data->>'destination_id','')::uuid,gen_random_uuid());
   if p_data->>'target'='task' then insert into public.mvp_tasks(id,user_id,title,description,source_inbox_id)values(destination,uid,p_data->>'title',capture.content,id);update public.mvp_inbox_items set status='processed',processed_at=now(),converted_task_id=destination where mvp_inbox_items.id=id;
   elsif p_data->>'target'='project' then insert into public.mvp_projects(id,user_id,title,outcome)values(destination,uid,p_data->>'title',capture.content);update public.mvp_inbox_items set status='processed',processed_at=now(),converted_project_id=destination where mvp_inbox_items.id=id;
   elsif p_data->>'target'='artifact' then insert into public.mvp_artifacts(id,user_id,source_inbox_id,kind,title,content,storage_key)values(destination,uid,id,'note',p_data->>'title',capture.content,capture.file_key);update public.mvp_inbox_items set status='processed',processed_at=now(),converted_artifact_id=destination where mvp_inbox_items.id=id;
   else raise exception 'Invalid conversion target';end if;result=jsonb_build_object('id',destination,'target',p_data->>'target');end if;
 when 'start_focus' then
  select * into task from public.mvp_tasks where mvp_tasks.id=(p_data->>'task_id')::uuid and user_id=uid and deleted_at is null and cancelled_at is null and status<>'done';if not found then raise exception 'Choose an unfinished task';end if;
  insert into public.mvp_focus_sessions(id,user_id,task_id,planned_seconds)values(coalesce(id,gen_random_uuid()),uid,task.id,coalesce((p_data->>'planned_seconds')::int,1500))returning to_jsonb(mvp_focus_sessions.*)into result;
 when 'pause_focus','resume_focus','end_focus' then
  select * into focus from public.mvp_focus_sessions where mvp_focus_sessions.id=id and user_id=uid and deleted_at is null for update;if not found then raise exception using errcode='42501',message='Focus session unavailable';end if;perform public.mvp_check_version(focus.version,p_data);if focus.status='ended' then raise exception 'Session already ended';end if;
  update public.mvp_focus_sessions set status=case p_command when 'pause_focus'then 'paused' when 'resume_focus'then 'running' else 'ended' end,ended_at=case when p_command='end_focus'then now()else null end,outcome=p_data->>'outcome',strategy_tried=p_data->>'strategy',helpfulness=p_data->>'helpfulness',lesson=p_data->>'lesson' where mvp_focus_sessions.id=id returning to_jsonb(mvp_focus_sessions.*)into result;
 when 'finish_project' then
  select * into project from public.mvp_projects where mvp_projects.id=id and user_id=uid and deleted_at is null for update;if not found then raise exception using errcode='42501',message='Project unavailable';end if;perform public.mvp_check_version(project.version,p_data);
  if nullif(trim(project.definition_of_done),'')is null or not coalesce((p_data->>'checklist_confirmed')::boolean,false)then raise exception 'Confirm the saved definition of done';end if;
  if coalesce((pref->>'requireEvidence')::boolean,true) and nullif(trim(p_data->>'evidence'),'')is null then raise exception 'Completion evidence required';end if;
  if exists(select 1 from public.mvp_tasks where project_id=id and user_id=uid and status<>'done' and cancelled_at is null and deleted_at is null)then
   if p_data->>'unfinished'='cancel' then update public.mvp_tasks set cancelled_at=now(),cancel_reason='Cancelled in finish review',today_date=null where project_id=id and user_id=uid and status<>'done' and deleted_at is null;
   elsif p_data->>'unfinished'='backlog' then update public.mvp_tasks set project_id=null,parent_id=null,today_date=null where project_id=id and user_id=uid and status<>'done' and cancelled_at is null and deleted_at is null;
   else raise exception 'Resolve unfinished tasks explicitly';end if;
  end if;
  insert into public.mvp_artifacts(user_id,project_id,kind,title,content)values(uid,id,'output','Finished: '||project.title,coalesce(nullif(p_data->>'evidence',''),'Finish checklist confirmed.'))returning mvp_artifacts.id into artifact_id;
  update public.mvp_projects set status='completed',progress=100,completed_at=now(),next_action_task_id=null,last_activity_at=now()where mvp_projects.id=id returning to_jsonb(mvp_projects.*)into result;result=result||jsonb_build_object('artifact_id',artifact_id);
 when 'save_brief' then
  if exists(select 1 from jsonb_array_elements_text(coalesce(p_data->'task_ids','[]')) x where not exists(select 1 from public.mvp_tasks t where t.id=x.value::uuid and t.user_id=uid and t.deleted_at is null))then raise exception 'Brief references an unavailable task';end if;
  insert into public.mvp_daily_briefs(user_id,local_date,time_zone_snapshot,task_ids,explanation)values(uid,(p_data->>'local_date')::date,(select time_zone from public.mvp_users where mvp_users.id=uid),array(select x.value::uuid from jsonb_array_elements_text(coalesce(p_data->'task_ids','[]'))x),coalesce(p_data->>'explanation',''))on conflict(user_id,local_date)do update set task_ids=excluded.task_ids,explanation=excluded.explanation,generated_at=now(),version=mvp_daily_briefs.version+1 returning to_jsonb(mvp_daily_briefs.*)into result;
 else raise exception 'Unsupported command';
 end case;
 insert into public.mvp_mutation_receipts(user_id,mutation_id,request_hash,result)values(uid,p_mutation_id,hash,result);return result;
end$$;
-- Every client write goes through mvp_command, which serializes each user's mutations.
do $$declare name text;begin foreach name in array array['mvp_users','mvp_settings','mvp_projects','mvp_tasks','mvp_inbox_items','mvp_artifacts','mvp_daily_briefs','mvp_focus_sessions','mvp_mutation_receipts','mvp_recurrence_occurrences']loop execute format('alter table public.%I enable row level security',name);if name='mvp_users'then execute format('create policy owner_read on public.%I for select to authenticated using(id=auth.uid())',name);else execute format('create policy owner_read on public.%I for select to authenticated using(user_id=auth.uid())',name);end if;execute format('revoke all on public.%I from anon,authenticated',name);execute format('grant select on public.%I to authenticated',name);end loop;end$$;
revoke all on function public.mvp_command(uuid,text,jsonb)from public,anon;
grant execute on function public.mvp_command(uuid,text,jsonb)to authenticated;
commit;
